import Vue from 'vue'
import Router from 'vue-router'
import HomePage from '@/views/HomePage'
import AboutPage from '@/views/AboutPage'
import MoralEducation from '@/views/MoralEducation'

Vue.use(Router)

export default new Router({
  routes: [
    {
      path: '/',
      name: 'HomePage',
      component: HomePage
    },
    {
      path: '/about',
      name: 'AboutPage',
      component: AboutPage
    },
    {
      path: '/moral-education',
      name: 'MoralEducation',
      component: MoralEducation
    }
  ]
})
